(function(){'use strict';function cloneTemplate(templateId){const template=document.getElementById(templateId);if(!template||!template.content)return null;return template.content.cloneNode(true);}
function addMegaFooters(){document.querySelectorAll('.mega-stage').forEach(stage=>{if(stage.querySelector(':scope > .mfooter'))return;const footer=cloneTemplate('caviarMegaFooterTemplate');if(footer)stage.appendChild(footer);});}
function isHashOrVoidUrl(url){if(url===null||url===undefined)return true;const value=String(url).trim().toLowerCase();return(value===''||value==='#'||value==='javascript:void(0)'||value==='javascript:void(0);');}
function isInactiveLink(link){const select=link.closest('[data-select]');if(select&&link.hasAttribute('data-select-option')&&(link.dataset.url||link.dataset.href||link.dataset.param||select.dataset.param)){return false;}
return isHashOrVoidUrl(link.getAttribute('href'));}
document.addEventListener('click',event=>{const link=event.target.closest('a');if(!link||!link.closest('.header-menu, #mobileMenu'))return;if(!isInactiveLink(link))return;event.preventDefault();});function closeSelect(select){const button=select.querySelector('[data-select-btn]');select.classList.remove('open');if(button)button.setAttribute('aria-expanded','false');}
function closeAllSelects(exceptSelect){document.querySelectorAll('[data-select].open').forEach(select=>{if(select!==exceptSelect)closeSelect(select);});}
function openSelect(select){const button=select.querySelector('[data-select-btn]');closeAllSelects(select);select.classList.add('open');if(button)button.setAttribute('aria-expanded','true');}
function toggleSelect(select){if(select.classList.contains('open')){closeSelect(select);}else{openSelect(select);}}
function getSelectValue(option){return option.dataset.value||option.textContent.trim();}
function getOptionUrl(select,option){const href=option.getAttribute('href');if(!isHashOrVoidUrl(href))return href;if(!isHashOrVoidUrl(option.dataset.url))return option.dataset.url;if(!isHashOrVoidUrl(option.dataset.href))return option.dataset.href;const param=option.dataset.param||select.dataset.param;const value=getSelectValue(option);if(param&&value){const url=new URL(window.location.href);url.searchParams.set(param,value);return url.toString();}
return'';}
function isModifiedClick(event){return event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||event.button!==0;}
function setSelectedOption(select,option){const current=select.querySelector('[data-select-current]');const value=getSelectValue(option);if(current&&value)current.textContent=value;select.querySelectorAll('[data-select-option]').forEach(item=>{item.setAttribute('aria-selected',String(item===option));const li=item.closest('[role="option"]');if(li)li.setAttribute('aria-selected',String(item===option));});}
function prepareSelectAccessibility(select,index){const button=select.querySelector('[data-select-btn]');const menu=select.querySelector('[data-select-menu]');if(!button||!menu)return;if(!menu.id)menu.id=`site-select-menu-${index+1}`;button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls',menu.id);if(!menu.getAttribute('role'))menu.setAttribute('role','listbox');select.querySelectorAll('[data-select-option]').forEach(option=>{if(!option.hasAttribute('aria-selected')){option.setAttribute('aria-selected','false');}});}
function initUniversalSelects(){const selects=document.querySelectorAll('[data-select]');selects.forEach((select,index)=>{prepareSelectAccessibility(select,index);const button=select.querySelector('[data-select-btn]');const options=select.querySelectorAll('[data-select-option]');if(button){button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();toggleSelect(select);});}
options.forEach(option=>{option.addEventListener('click',event=>{if(option.tagName.toLowerCase()==='a'&&isModifiedClick(event)){closeAllSelects();return;}
event.preventDefault();event.stopPropagation();setSelectedOption(select,option);closeAllSelects();const url=getOptionUrl(select,option);if(url){window.location.href=url;}});});});}
const body=document.body;const openBtn=document.querySelector('.menu-btn')||document.getElementById('open');const closeBtn=document.getElementById('close');const scrim=document.getElementById('scrim');const mobileMenu=document.getElementById('mobileMenu');function resetMobileMenu(){if(!mobileMenu)return;mobileMenu.classList.remove('sub-open');const sub=mobileMenu.querySelector('.mobile-panel.sub');if(sub)sub.innerHTML='';}
function openDrawer(){body.classList.add('open');resetMobileMenu();}
function closeDrawer(){body.classList.remove('open');resetMobileMenu();}
function toggleDrawer(){if(body.classList.contains('open')){closeDrawer();}else{openDrawer();}}
if(openBtn&&!openBtn.dataset.caviarDrawerBound){openBtn.dataset.caviarDrawerBound='1';openBtn.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();toggleDrawer();});}
if(closeBtn&&closeBtn!==openBtn&&!closeBtn.dataset.caviarDrawerBound){closeBtn.dataset.caviarDrawerBound='1';closeBtn.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();closeDrawer();});}
if(scrim&&!scrim.dataset.caviarDrawerBound){scrim.dataset.caviarDrawerBound='1';scrim.addEventListener('click',event=>{event.stopPropagation();closeDrawer();});}
function makeMobileLink(src,className){const a=document.createElement('a');const href=src.getAttribute('href');if(href)a.setAttribute('href',href);a.textContent=src.textContent.trim();if(className)a.className=className;a.addEventListener('click',closeDrawer);return a;}
function fillMobileSubmenu(content,li){const cols=li.querySelectorAll(':scope .cols .col');const botLinks=li.querySelectorAll(':scope .botlinks a');const feature=li.querySelector(':scope .feature');cols.forEach(col=>{const groupTitle=col.querySelector(':scope .gh');if(groupTitle&&groupTitle.textContent.trim()){const h4=document.createElement('h4');h4.textContent=groupTitle.textContent.trim();content.appendChild(h4);}
col.querySelectorAll(':scope .items a').forEach(a=>{content.appendChild(makeMobileLink(a));});});botLinks.forEach(a=>{content.appendChild(makeMobileLink(a,'muted'));});if(feature){const title=feature.querySelector('h5');const text=(title?title.textContent:feature.textContent).trim();if(text){const link=document.createElement('a');const href=feature.getAttribute('href');if(href)link.setAttribute('href',href);link.className='muted feature-link';link.textContent=text;link.addEventListener('click',closeDrawer);content.appendChild(link);}}}
function openMobileSubmenu(title,li){if(!mobileMenu)return;const sub=mobileMenu.querySelector('.mobile-panel.sub');if(!sub)return;const backName=mobileMenu.dataset.backName||'Back';sub.innerHTML='';const head=document.createElement('div');head.className='mobile-subhead';const back=document.createElement('button');back.type='button';back.className='mobile-back';back.textContent=backName;back.addEventListener('click',()=>mobileMenu.classList.remove('sub-open'));const h3=document.createElement('h3');h3.textContent=title;head.append(back,h3);const content=document.createElement('div');content.className='mobile-subcontent';fillMobileSubmenu(content,li);sub.append(head,content);mobileMenu.classList.add('sub-open');sub.scrollTop=0;}
function buildMobileMenu(){if(!mobileMenu)return;const items=document.querySelectorAll('.header-menu > ul > li');if(!items.length)return;mobileMenu.innerHTML='';const panels=document.createElement('div');panels.className='mobile-panels';const root=document.createElement('div');root.className='mobile-panel root';const sub=document.createElement('div');sub.className='mobile-panel sub';panels.append(root,sub);mobileMenu.appendChild(panels);items.forEach(li=>{const top=li.querySelector(':scope > a');if(!top)return;const title=top.textContent.trim();const hasSubmenu=!!li.querySelector(':scope .cols .col, :scope .botlinks a, :scope .feature');const row=document.createElement('div');row.className='mobile-row';if(hasSubmenu){const btn=document.createElement('button');btn.type='button';btn.append(document.createTextNode(title));const arrow=document.createElement('span');arrow.className='mobile-arrow';btn.appendChild(arrow);btn.addEventListener('click',()=>openMobileSubmenu(title,li));row.appendChild(btn);}else{row.appendChild(makeMobileLink(top));}
root.appendChild(row);});}
let closeTimer=null;let currentItem=null;function openMega(li){if(closeTimer){clearTimeout(closeTimer);closeTimer=null;}
if(currentItem&&currentItem!==li){closeMegaItem(currentItem);}
const mega=li.querySelector(':scope .mega');if(!mega)return;li.classList.add('on');mega.classList.add('open');currentItem=li;}
function closeMegaItem(li){li.classList.remove('on');const mega=li.querySelector(':scope .mega');if(mega)mega.classList.remove('open');if(currentItem===li)currentItem=null;}
function closeMega(){if(currentItem)closeMegaItem(currentItem);if(closeTimer){clearTimeout(closeTimer);closeTimer=null;}}
function scheduleMegaClose(){if(closeTimer)clearTimeout(closeTimer);closeTimer=setTimeout(()=>{if(currentItem)closeMegaItem(currentItem);},200);}
function initMegaMenu(){document.querySelectorAll('.header-menu > ul > li[data-menu]').forEach(li=>{const mega=li.querySelector(':scope .mega');const top=li.querySelector(':scope > a');if(!mega||!top)return;li.addEventListener('mouseenter',()=>openMega(li));li.addEventListener('mouseleave',scheduleMegaClose);top.addEventListener('focus',()=>openMega(li));mega.addEventListener('mouseenter',()=>{if(closeTimer){clearTimeout(closeTimer);closeTimer=null;}});mega.addEventListener('mouseleave',scheduleMegaClose);});}
function initSearch(){const search=document.querySelector('.search');const searchBtn=document.getElementById('searchBtn');const searchInput=document.getElementById('searchInput');if(!search||!searchBtn||!searchInput)return;searchBtn.addEventListener('click',event=>{event.stopPropagation();const isOpen=search.classList.toggle('open');if(isOpen)searchInput.focus();});document.addEventListener('click',event=>{if(!search.contains(event.target)&&!searchInput.value){search.classList.remove('open');}});}
document.addEventListener('click',event=>{if(!event.target.closest('[data-select]')){closeAllSelects();}});document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeDrawer();closeMega();closeAllSelects();}});addMegaFooters();initUniversalSelects();buildMobileMenu();initMegaMenu();initSearch();})();